/// 校验是否为合法 Go duration 字面量形式。
fn validate_go_duration(value: &str) -> Result<(), String> {
    // time.quote escapes every non-ASCII/control byte rather than Unicode scalars.
    let quote = |value: &str| {
        let mut result = String::from("\"");
        for byte in value.bytes() {
            match byte {
                b'"' | b'\\' => {
                    result.push('\\');
                    result.push(byte as char);
                }
                0..=31 | 128..=255 => result.push_str(&format!("\\x{byte:02x}")),
                _ => result.push(byte as char),
            }
        }
        result.push('"');
        result
    };
    let original = quote(value);
    let invalid_duration = || format!("time: invalid duration {original}");
    // Match time.ParseDuration, including its signed int64 nanosecond range
    // and bounded fractional accumulation.
    let negative = value.starts_with('-');
    let value = value.strip_prefix(['+', '-']).unwrap_or(value);
    if value == "0" {
        return Ok(());
    }
    let bytes = value.as_bytes();
    let mut index = 0;
    let mut total = 0u64;
    const LIMIT: u64 = 1 << 63;
    while index < bytes.len() {
        let start = index;
        let mut integer = 0u64;
        while index < bytes.len() && bytes[index].is_ascii_digit() {
            let digit = u64::from(bytes[index] - b'0');
            if integer > (LIMIT - digit) / 10 {
                return Err(invalid_duration());
            }
            integer = integer * 10 + digit;
            index += 1;
        }
        let pre = index > start;
        let mut fraction = 0u64;
        let mut scale = 1.0f64;
        let mut post = false;
        if index < bytes.len() && bytes[index] == b'.' {
            index += 1;
            let mut overflow = false;
            while index < bytes.len() && bytes[index].is_ascii_digit() {
                post = true;
                if !overflow {
                    let digit = u64::from(bytes[index] - b'0');
                    if fraction > (LIMIT - 1) / 10 || fraction * 10 + digit > LIMIT {
                        overflow = true;
                    } else {
                        fraction = fraction * 10 + digit;
                        scale *= 10.0;
                    }
                }
                index += 1;
            }
        }
        if !pre && !post {
            return Err(invalid_duration());
        }
        let unit_start = index;
        while index < bytes.len() && bytes[index] != b'.' && !bytes[index].is_ascii_digit() {
            index += 1;
        }
        let unit = match &value[unit_start..index] {
            "ns" => 1,
            "us" | "µs" | "μs" => 1_000,
            "ms" => 1_000_000,
            "s" => 1_000_000_000,
            "m" => 60_000_000_000,
            "h" => 3_600_000_000_000,
            "" => return Err(format!("time: missing unit in duration {original}")),
            unit => {
                return Err(format!(
                    "time: unknown unit {} in duration {original}",
                    quote(unit)
                ));
            }
        };
        if integer > LIMIT / unit {
            return Err(invalid_duration());
        }
        let term = integer * unit + (fraction as f64 * (unit as f64 / scale)) as u64;
        if term > LIMIT || total > LIMIT - term {
            return Err(invalid_duration());
        }
        total += term;
    }
    if !value.is_empty() && (negative || total < LIMIT) {
        Ok(())
    } else {
        Err(invalid_duration())
    }
}

