/// 校验列定义合法性（生成列选项等）。
fn validate_column_def(column: &parser_ast::ColumnDef) -> Result<(), errors::Error> {
    let generated = column
        .Options
        .iter()
        .any(|option| option.Tp == parser_ast::ColumnOptionType::Generated);
    if !generated {
        return Ok(());
    }
    let illegal = column
        .Options
        .iter()
        .rev()
        .find_map(|option| match option.Tp {
            parser_ast::ColumnOptionType::AutoIncrement => Some("AUTO_INCREMENT"),
            parser_ast::ColumnOptionType::OnUpdate => Some("ON UPDATE"),
            parser_ast::ColumnOptionType::DefaultValue => Some("DEFAULT"),
            _ => None,
        });
    match illegal {
        Some(illegal) => {
            Err(AST_ERR_WRONG_USAGE
                .GenWithStackByArgs(&[illegal.into(), "generated column".into()]))
        }
        None => Ok(()),
    }
}

/// 校验分区定义子句与分区方法是否匹配。
fn validate_partition_clause(
    clause: &parser_ast::PartitionDefinitionClause,
    partition_type: parser_ast::PartitionType,
    columns: usize,
) -> Result<(), errors::Error> {
    use parser_ast::{PartitionDefinitionClause as Clause, PartitionType as Type};
    let validation_error = |code: u16, args: &[&str]| {
        Err(terror::ClassDDL
            .NewStd(terror::ErrCode(code as isize))
            .GenWithStackByArgs(&args.iter().map(|value| (*value).into()).collect::<Vec<_>>()))
    };
    match clause {
        Clause::None => match partition_type {
            Type::Range => {
                validation_error(mysql::ErrPartitionRequiresValues, &["RANGE", "LESS THAN"])
            }
            Type::List => validation_error(mysql::ErrPartitionRequiresValues, &["LIST", "IN"]),
            Type::SystemTime => validation_error(mysql::ErrSystemVersioningWrongPartitions, &[]),
            _ => Ok(()),
        },
        Clause::LessThan(expressions) => {
            if !matches!(partition_type, Type::Range | Type::None) {
                return validation_error(mysql::ErrPartitionWrongValues, &["RANGE", "LESS THAN"]);
            }
            if columns == 0 && expressions.len() != 1 {
                return validation_error(mysql::ErrTooManyValues, &["RANGE"]);
            }
            if columns > 0 && expressions.len() != columns {
                return validation_error(mysql::ErrPartitionColumnList, &[]);
            }
            Ok(())
        }
        Clause::In(values) => {
            if !matches!(partition_type, Type::List | Type::None) {
                return validation_error(mysql::ErrPartitionWrongValues, &["LIST", "IN"]);
            }
            if values.is_empty() {
                return Ok(());
            }
            let mut expected = values[0].len();
            let mut start = 1;
            if expected == 1 && matches!(values[0][0].Kind, parser_ast::ExprKind::DefaultValue) {
                if values.len() == 1 {
                    return Ok(());
                }
                expected = values[1].len();
                start = 2;
            }
            for value in &values[start..] {
                if value.len() != expected
                    && !(value.len() == 1
                        && matches!(value[0].Kind, parser_ast::ExprKind::DefaultValue))
                {
                    return validation_error(mysql::ErrPartitionColumnList, &[]);
                }
            }
            if columns == 0 && expected != 1 {
                return validation_error(mysql::ErrRowSinglePartitionField, &[]);
            }
            if columns > 0 && expected != columns {
                return validation_error(mysql::ErrPartitionColumnList, &[]);
            }
            Ok(())
        }
        Clause::History { .. } if !matches!(partition_type, Type::SystemTime | Type::None) => {
            validation_error(mysql::ErrWrongPartitionTypeExpectedSystemTime, &[])
        }
        Clause::History { .. } => Ok(()),
    }
}

/// 校验并规范化整表分区选项。
fn validate_partition_options(
    options: &mut parser_ast::PartitionOptions,
) -> Result<(), errors::Error> {
    use parser_ast::PartitionType as Type;
    let validation_error = |code: u16, args: &[&str]| {
        Err(terror::ClassDDL
            .NewStd(terror::ErrCode(code as isize))
            .GenWithStackByArgs(&args.iter().map(|value| (*value).into()).collect::<Vec<_>>()))
    };
    if options.PartitionMethod.Num != 0
        && !options.Definitions.is_empty()
        && options.PartitionMethod.Num != options.Definitions.len() as u64
    {
        return validation_error(mysql::ErrPartitionWrongNoPart, &[]);
    }
    if let Some(first) = options.Definitions.first() {
        options.PartitionMethod.Num = options.Definitions.len() as u64;
        let sub_count = first.Sub.len();
        if options
            .Definitions
            .iter()
            .skip(1)
            .any(|definition| definition.Sub.len() != sub_count)
        {
            return validation_error(mysql::ErrPartitionWrongNoSubpart, &[]);
        }
        if let Some(sub) = options.Sub.as_mut() {
            if sub.Num != 0 && sub_count != 0 && sub.Num != sub_count as u64 {
                return validation_error(mysql::ErrPartitionWrongNoSubpart, &[]);
            }
            if sub_count != 0 {
                sub.Num = sub_count as u64;
            }
        } else if sub_count != 0 {
            return validation_error(mysql::ErrSubpartition, &[]);
        }
    }
    match options.PartitionMethod.Tp {
        Type::Hash | Type::Key if options.PartitionMethod.Num == 0 => {
            options.PartitionMethod.Num = 1
        }
        Type::Range | Type::List
            if options.PartitionMethod.Interval.is_none() && options.Definitions.is_empty() =>
        {
            return validation_error(
                mysql::ErrPartitionsMustBeDefined,
                &[if options.PartitionMethod.Tp == Type::Range {
                    "RANGE"
                } else {
                    "LIST"
                }],
            );
        }
        Type::SystemTime if options.Definitions.len() < 2 => {
            return validation_error(mysql::ErrSystemVersioningWrongPartitions, &[]);
        }
        _ => {}
    }
    for definition in &options.Definitions {
        validate_partition_clause(
            &definition.Clause,
            options.PartitionMethod.Tp,
            options.PartitionMethod.ColumnNames.len(),
        )?;
    }
    Ok(())
}

/// 按名称解析数据脱敏策略限制操作；未知返回 (None, false)。
pub fn getMaskingPolicyRestrictOp(name: &str) -> (ast::MaskingPolicyRestrictOps, bool) {
    // Go 先把名称转成大写再匹配四种限制操作；未知名称显式返回 None/false。
    match name.to_uppercase().as_str() {
        ast::MaskingPolicyRestrictNameInsertIntoSelect => {
            (ast::MaskingPolicyRestrictOpInsertIntoSelect, true)
        }
        ast::MaskingPolicyRestrictNameUpdateSelect => {
            (ast::MaskingPolicyRestrictOpUpdateSelect, true)
        }
        ast::MaskingPolicyRestrictNameDeleteSelect => {
            (ast::MaskingPolicyRestrictOpDeleteSelect, true)
        }
        ast::MaskingPolicyRestrictNameCTAS => (ast::MaskingPolicyRestrictOpCTAS, true),
        _ => (ast::MaskingPolicyRestrictOpNone, false),
    }
}

fn semantic_value_text(value: &dyn Any) -> String {
    if let Some(value) = value.downcast_ref::<i64>() {
        value.to_string()
    } else if let Some(value) = value.downcast_ref::<u64>() {
        value.to_string()
    } else if let Some(value) = value.downcast_ref::<f64>() {
        value.to_string()
    } else if let Some(value) = value.downcast_ref::<String>() {
        value.clone()
    } else if let Some(value) = value.downcast_ref::<bool>() {
        value.to_string()
    } else if let Some(value) = value.downcast_ref::<Value>() {
        match value {
            Value::Null => "NULL".to_owned(),
            Value::String(value) => value.clone(),
        }
    } else if let Some(value) = value.downcast_ref::<parser_test_driver::MyDecimal>() {
        value.String()
    } else if let Some(value) = value.downcast_ref::<parser_test_driver::HexLiteral>() {
        format!(
            "0x{}",
            value
                .0
                .iter()
                .map(|byte| format!("{byte:02x}"))
                .collect::<String>()
        )
    } else if let Some(value) = value.downcast_ref::<parser_test_driver::BitLiteral>() {
        format!(
            "0b{}",
            value
                .0
                .iter()
                .map(|byte| format!("{byte:08b}"))
                .collect::<String>()
        )
    } else {
        "<value>".to_owned()
    }
}

/// Convert lexer semantic values without erasing their SQL datum kind. This is
/// the Rust counterpart of test_driver.newValueExpr + DefaultTypeForValue.
fn semantic_value_expr(
    value: &dyn Any,
    charset_name: &str,
    collation: &str,
) -> parser_ast::ExprNode {
    if value.is::<()>() {
        parser_ast::ExprNode::NullValue()
    } else if let Some(value) = value.downcast_ref::<bool>() {
        parser_ast::ExprNode::BoolValue(*value)
    } else if let Some(value) = value.downcast_ref::<i32>() {
        parser_ast::ExprNode::IntValue(*value as i64)
    } else if let Some(value) = value.downcast_ref::<i64>() {
        parser_ast::ExprNode::IntValue(*value)
    } else if let Some(value) = value.downcast_ref::<u64>() {
        parser_ast::ExprNode::UintValue(*value)
    } else if let Some(value) = value.downcast_ref::<f32>() {
        parser_ast::ExprNode::Float32Value(*value)
    } else if let Some(value) = value.downcast_ref::<f64>() {
        parser_ast::ExprNode::FloatValue(*value)
    } else if let Some(value) = value.downcast_ref::<String>() {
        parser_ast::ExprNode::StringValue(value.clone(), charset_name, collation)
    } else if let Some(value) = value.downcast_ref::<Value>() {
        match value {
            Value::Null => parser_ast::ExprNode::NullValue(),
            Value::String(value) => {
                parser_ast::ExprNode::StringValue(value.clone(), charset_name, collation)
            }
        }
    } else if let Some(value) = value.downcast_ref::<parser_test_driver::MyDecimal>() {
        parser_ast::ExprNode::DecimalValue(value.String())
    } else if let Some(value) = value.downcast_ref::<parser_test_driver::HexLiteral>() {
        parser_ast::ExprNode::HexValue(value.0.clone(), charset_name, collation)
    } else if let Some(value) = value.downcast_ref::<parser_test_driver::BitLiteral>() {
        parser_ast::ExprNode::BitValue(value.0.clone(), charset_name, collation)
    } else {
        panic!("unsupported lexer literal semantic type")
    }
}

fn semantic_numeric_isize(value: &dyn Any) -> Option<isize> {
    if let Some(value) = value.downcast_ref::<u64>() {
        Some(*value as isize)
    } else if let Some(value) = value.downcast_ref::<i64>() {
        Some(*value as isize)
    } else if let Some(value) = value.downcast_ref::<isize>() {
        Some(*value)
    } else if let Some(value) = value.downcast_ref::<usize>() {
        Some(*value as isize)
    } else {
        semantic_value_text(value).parse().ok()
    }
}

fn result_set_from_item(item: &dyn Any) -> Option<parser_ast::ResultSetNode> {
    if let Some(source) = item.downcast_ref::<parser_ast::TableSource>() {
        Some(parser_ast::ResultSetNode::TableSource(source.clone()))
    } else {
        item.downcast_ref::<parser_ast::Join>()
            .cloned()
            .map(|join| parser_ast::ResultSetNode::Join(Box::new(join)))
    }
}
